// --- wt.FDb._db.InsertStrptrMaybe
// Parse strptr into known type and add to database.
// Return value is true unless an error occurs. If return value is false, algo_lib::_db.errtext has error text
bool wt::InsertStrptrMaybe(algo::strptr str) {
    bool retval = true;
    wt::TableId table_id(-1);
    value_SetStrptrMaybe(table_id, algo::GetTypeTag(str));
    switch (value_GetEnum(table_id)) {
        case wt_TableId_dev_Sandbox: { // finput:wt.FDb.sandbox
            dev::Sandbox elem;
            retval = dev::Sandbox_ReadStrptrMaybe(elem, str);
            retval = retval && sandbox_InputMaybe(elem);
            break;
        }
        case wt_TableId_dev_Sbpath: { // finput:wt.FDb.sbpath
            dev::Sbpath elem;
            retval = dev::Sbpath_ReadStrptrMaybe(elem, str);
            retval = retval && sbpath_InputMaybe(elem);
            break;
        }
        default:
        break;
    } //switch
    if (!retval) {
        algo_lib::NoteInsertErr(str); // increment error counter
    }
    return retval;
}

// --- wt.FDb._db.LoadTuplesMaybe
// Load all finputs from given directory.
bool wt::LoadTuplesMaybe(algo::strptr root, bool recursive) {
    bool retval = true;
    if (FileQ(root)) {
        retval = wt::LoadTuplesFile(root, recursive);
    } else if (root == "-") {
        retval = wt::LoadTuplesFd(algo::Fildes(0),"(stdin)",recursive);
    } else if (DirectoryQ(root)) {
        retval = retval && wt::LoadTuplesFile(algo::SsimFname(root,"dmmeta.dispsigcheck"),recursive);
        retval = retval && wt::LoadTuplesFile(algo::SsimFname(root,"dev.sbpath"),recursive);
        retval = retval && wt::LoadTuplesFile(algo::SsimFname(root,"dev.sandbox"),recursive);
    } else {
        algo_lib::AppendErrtext("path", root);
        algo_lib::AppendErrtext("comment", "Wrong working directory?");
        retval = false;
    }
    return retval;
}

// --- wt.FDb._db.LoadTuplesFile
// Load all finputs from given file.
// Read tuples from file FNAME into this namespace's in-memory database.
// If RECURSIVE is TRUE, then also load these tuples into any parent namespaces
// It a file referred to by FNAME is missing, no error is reported (it's considered an empty set).
// Function returns TRUE if all records were parsed and inserted without error.
// If the function returns FALSE, use algo_lib::DetachBadTags() for error description
bool wt::LoadTuplesFile(algo::strptr fname, bool recursive) {
    bool retval = true;
    algo_lib::FFildes fildes;
    // missing files are not an error
    fildes.fd = OpenRead(fname,algo::FileFlags());
    if (ValidQ(fildes.fd)) {
        retval = LoadTuplesFd(fildes.fd, fname, recursive);
    }
    return retval;
}

// --- wt.FDb._db.LoadTuplesFd
// Load all finputs from given file descriptor.
bool wt::LoadTuplesFd(algo::Fildes fd, algo::strptr fname, bool recursive) {
    bool retval = true;
    ind_beg(algo::FileLine_curs,line,fd) {
        if (recursive) {
            retval = retval && algo_lib::InsertStrptrMaybe(line);
        }
        retval = retval && wt::InsertStrptrMaybe(line);
        if (!retval) {
            algo_lib::_db.errtext << eol
            << fname << ":"
            << (ind_curs(line).i+1)
            << ": " << line << eol;
            break;
        }
    }ind_end;
    return retval;
}

