// --- wt.FDb.sandbox.AllocMem
// Allocate space for one element. If no memory available, return NULL.
void* wt::sandbox_AllocMem() {
    u64 new_nelems     = _db.sandbox_n+1;
    // compute level and index on level
    u64 bsr   = algo::u64_BitScanReverse(new_nelems);
    u64 base  = u64(1)<<bsr;
    u64 index = new_nelems-base;
    void *ret = NULL;
    // if level doesn't exist yet, create it
    wt::FSandbox*  lev   = NULL;
    if (bsr < 36) {
        lev = _db.sandbox_lary[bsr];
        if (!lev) {
            lev=(wt::FSandbox*)algo_lib::malloc_AllocMem(sizeof(wt::FSandbox) * (u64(1)<<bsr));
            _db.sandbox_lary[bsr] = lev;
        }
    }
    // allocate element from this level
    if (lev) {
        _db.sandbox_n = i64(new_nelems);
        ret = lev + index;
    }
    return ret;
}

// --- wt.FDb.sandbox.RemoveAll
// Remove all elements from Lary
void wt::sandbox_RemoveAll() {
    for (u64 n = _db.sandbox_n; n>0; ) {
        n--;
        sandbox_qFind(u64(n)).~FSandbox(); // destroy last element
        _db.sandbox_n = i64(n);
    }
}

// --- wt.FDb.sandbox.RemoveLast
// Delete last element of array. Do nothing if array is empty.
void wt::sandbox_RemoveLast() {
    u64 n = _db.sandbox_n;
    if (n > 0) {
        n -= 1;
        sandbox_qFind(u64(n)).~FSandbox();
        _db.sandbox_n = i64(n);
    }
}

