wt::FSandbox& wt::ind_sandbox_GetOrCreate(const algo::strptr& key) {
    wt::FSandbox* ret = ind_sandbox_Find(key);
    if (!ret) { //  if memory alloc fails, process dies; if insert fails, function returns NULL.
        ret         = &sandbox_Alloc();
        (*ret).sandbox = key;
        bool good = sandbox_XrefMaybe(*ret);
        if (!good) {
            sandbox_RemoveLast(); // delete offending row, any existing xrefs are cleared
            ret = NULL;
        }
    }
    vrfy(ret, tempstr() << "wt.create_error  table:ind_sandbox  key:'"<<key<<"'  comment:'bad xref'");
    return *ret;
}

// --- wt.FDb.ind_sandbox.InsertMaybe
// Insert row into hash table. Return true if row is reachable through the hash after the function completes.
bool wt::ind_sandbox_InsertMaybe(wt::FSandbox& row) {
    bool retval = true; // if already in hash, InsertMaybe returns true
    if (LIKELY(row.ind_sandbox_next == (wt::FSandbox*)-1)) {// check if in hash already
        row.ind_sandbox_hashval = algo::Smallstr50_Hash(0, row.sandbox);
        ind_sandbox_Reserve(1);
        u32 index = row.ind_sandbox_hashval & (_db.ind_sandbox_buckets_n - 1);
        wt::FSandbox* *prev = &_db.ind_sandbox_buckets_elems[index];
        do {
            wt::FSandbox* ret = *prev;
            if (!ret) { // exit condition 1: reached the end of the list
                break;
            }
            if ((*ret).sandbox == row.sandbox) { // exit condition 2: found matching key
                retval = false;
                break;
            }
            prev = &ret->ind_sandbox_next;
        } while (true);
        if (retval) {
            row.ind_sandbox_next = *prev;
            _db.ind_sandbox_n++;
            *prev = &row;
        }
    }
    return retval;
}

// --- wt.FDb.ind_sandbox.Remove
// Remove reference to element from hash index. If element is not in hash, do nothing
void wt::ind_sandbox_Remove(wt::FSandbox& row) {
    if (LIKELY(row.ind_sandbox_next != (wt::FSandbox*)-1)) {// check if in hash already
        u32 index = row.ind_sandbox_hashval & (_db.ind_sandbox_buckets_n - 1);
        wt::FSandbox* *prev = &_db.ind_sandbox_buckets_elems[index]; // addr of pointer to current element
        while (wt::FSandbox *next = *prev) {                          // scan the collision chain for our element
            if (next == &row) {        // found it?
                *prev = next->ind_sandbox_next; // unlink (singly linked list)
                _db.ind_sandbox_n--;
                row.ind_sandbox_next = (wt::FSandbox*)-1;// not-in-hash
                break;
            }
            prev = &next->ind_sandbox_next;
        }
    }
}

// --- wt.FDb.ind_sandbox.Reserve
// Reserve enough room in the hash for N more elements. Return success code.
void wt::ind_sandbox_Reserve(int n) {
    ind_sandbox_AbsReserve(_db.ind_sandbox_n + n);
}

// --- wt.FDb.ind_sandbox.AbsReserve
// Reserve enough room for exacty N elements. Return success code.
void wt::ind_sandbox_AbsReserve(int n) {
    u32 old_nbuckets = _db.ind_sandbox_buckets_n;
    u32 new_nelems   = n;
    // # of elements has to be roughly equal to the number of buckets
    if (new_nelems > old_nbuckets) {
        int new_nbuckets = i32_Max(algo::BumpToPow2(new_nelems), u32(4));
        u32 old_size = old_nbuckets * sizeof(wt::FSandbox*);
        u32 new_size = new_nbuckets * sizeof(wt::FSandbox*);
        // allocate new array. we don't use Realloc since copying is not needed and factor of 2 probably
        // means new memory will have to be allocated anyway
        wt::FSandbox* *new_buckets = (wt::FSandbox**)algo_lib::malloc_AllocMem(new_size);
        if (UNLIKELY(!new_buckets)) {
            FatalErrorExit("wt.out_of_memory  field:wt.FDb.ind_sandbox");
        }
        memset(new_buckets, 0, new_size); // clear pointers
        // rehash all entries
        for (int i = 0; i < _db.ind_sandbox_buckets_n; i++) {
            wt::FSandbox* elem = _db.ind_sandbox_buckets_elems[i];
            while (elem) {
                wt::FSandbox &row        = *elem;
                wt::FSandbox* next       = row.ind_sandbox_next;
                u32 index          = row.ind_sandbox_hashval & (new_nbuckets-1);
                row.ind_sandbox_next     = new_buckets[index];
                new_buckets[index] = &row;
                elem               = next;
            }
        }
        // free old array
        algo_lib::malloc_FreeMem(_db.ind_sandbox_buckets_elems, old_size);
        _db.ind_sandbox_buckets_elems = new_buckets;
        _db.ind_sandbox_buckets_n = new_nbuckets;
    }
}

