// --- wt.FDb..Init
// Set all fields to initial values.
void wt::FDb_Init() {
    // initialize LAry sandbox (wt.FDb.sandbox)
    _db.sandbox_n = 0;
    memset(_db.sandbox_lary, 0, sizeof(_db.sandbox_lary)); // zero out all level pointers
    wt::FSandbox* sandbox_first = (wt::FSandbox*)algo_lib::malloc_AllocMem(sizeof(wt::FSandbox) * (u64(1)<<4));
    if (!sandbox_first) {
        FatalErrorExit("out of memory");
    }
    for (int i = 0; i < 4; i++) {
        _db.sandbox_lary[i]  = sandbox_first;
        sandbox_first    += 1ULL<<i;
    }
    // initialize hash table for wt::FSandbox;
    _db.ind_sandbox_n             	= 0; // (wt.FDb.ind_sandbox)
    _db.ind_sandbox_buckets_n     	= 4; // (wt.FDb.ind_sandbox)
    _db.ind_sandbox_buckets_elems 	= (wt::FSandbox**)algo_lib::malloc_AllocMem(sizeof(wt::FSandbox*)*_db.ind_sandbox_buckets_n); // initial buckets (wt.FDb.ind_sandbox)
    if (!_db.ind_sandbox_buckets_elems) {
        FatalErrorExit("out of memory"); // (wt.FDb.ind_sandbox)
    }
    memset(_db.ind_sandbox_buckets_elems, 0, sizeof(wt::FSandbox*)*_db.ind_sandbox_buckets_n); // (wt.FDb.ind_sandbox)
    // initialize LAry sbpath (wt.FDb.sbpath)
    _db.sbpath_n = 0;
    memset(_db.sbpath_lary, 0, sizeof(_db.sbpath_lary)); // zero out all level pointers
    wt::FSbpath* sbpath_first = (wt::FSbpath*)algo_lib::malloc_AllocMem(sizeof(wt::FSbpath) * (u64(1)<<4));
    if (!sbpath_first) {
        FatalErrorExit("out of memory");
    }
    for (int i = 0; i < 4; i++) {
        _db.sbpath_lary[i]  = sbpath_first;
        sbpath_first    += 1ULL<<i;
    }

    wt::InitReflection();
}

