// --- wt.TableId.value.SetStrptrMaybe
// Convert string to field.
// If the string is invalid, do not modify field and return false.
// In case of success, return true
bool wt::value_SetStrptrMaybe(wt::TableId& parent, algo::strptr rhs) {
    bool ret = false;
    switch (elems_N(rhs)) {
        case 10: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('d','e','v','.','S','b','p','a'): {
                    if (memcmp(rhs.elems+8,"th",2)==0) { value_SetEnum(parent,wt_TableId_dev_Sbpath); ret = true; break; }
                    break;
                }
                case LE_STR8('d','e','v','.','s','b','p','a'): {
                    if (memcmp(rhs.elems+8,"th",2)==0) { value_SetEnum(parent,wt_TableId_dev_sbpath); ret = true; break; }
                    break;
                }
            }
            break;
        }
        case 11: {
            switch (algo::ReadLE64(rhs.elems)) {
                case LE_STR8('d','e','v','.','S','a','n','d'): {
                    if (memcmp(rhs.elems+8,"box",3)==0) { value_SetEnum(parent,wt_TableId_dev_Sandbox); ret = true; break; }
                    break;
                }
                case LE_STR8('d','e','v','.','s','a','n','d'): {
                    if (memcmp(rhs.elems+8,"box",3)==0) { value_SetEnum(parent,wt_TableId_dev_sandbox); ret = true; break; }
                    break;
                }
            }
            break;
        }
    }
    return ret;
}

